13.text:
 A virtual folder used to organize workspace resources. type Folder implements Node {
  id: ID!
  name: String!
  parent: String
  createdAt: DateTime!
}

25.text:
 Use Project instead for active workspace work. type LegacyProject {
  id: ID!
  name: String!
}

29.text:
 A paginated project result set. type ProjectConnection {
  nodes: [Project!]!
  totalCount: Int!
}

34.text:
 A change delivered to subscribers watching a project. type ProjectEvent {
  type: ProjectEventType!
  project: Project!
  actor: User
  occurredAt: DateTime!
}

54.text:
 A workspace member who owns and collaborates on projects. type User implements Node {
  id: ID!
  name: String!
  email: String!
  role: String!
}

63.text:
 A globally unique entity identifier. interface Node {
  id: ID!
}

67.text:
 Input used to create a project. input CreateProjectInput {
  name: String!
  ownerId: ID!
  folderId: ID
  status: ProjectStatus
}

74.text:
 The kind of change that occurred on a project. enum ProjectEventType {
  CREATED
  UPDATED
  ARCHIVED
}

79.text:
 The lifecycle stage of a project. enum ProjectStatus {
  DRAFT
  ACTIVE
  ARCHIVED
}

84.text:
 Marks an object type as superseded when standard @deprecated cannot be applied. directive @deprecatedType(
  reason: String!
) on OBJECT

91.text:
 Receive folders as they are created in the workspace. folderCreated(
  parentId: ID
): Folder!

94.text:
 subscription WatchFolders($parentId: ID) {
  folderCreated(parentId: $parentId) {
    id
    name
    parent
    createdAt
  }
}

95.text:
 Exposes a URL that specifies the behavior of this scalar. directive @specifiedBy(
  url: String!
) on SCALAR

101.text:
 subscription WatchProject($projectId: ID, $types: [ProjectEventType!]) {
  projectChanged(projectId: $projectId, types: $types) {
    type
    occurredAt
    project {
      id
      name
      status
    }
    actor {
      name
    }
  }
}

102.text:
 Fetch a single folder by its unique identifier. folder(
  id: ID!
): Folder

105.text:
 query GetFolder($id: ID!) {
  folder(id: $id) {
    id
    name
    parent
    createdAt
  }
}

110.text:
 query ListFolders {
  folders {
    id
    name
    parent
    createdAt
  }
}

111.text:
 Search folders, projects, and users from a single endpoint. search(
  query: String!
): [SearchResult!]!

114.text:
 query SearchWorkspace($query: String!) {
  search(query: $query) {
    __typename
    ... on Folder {
      id
      name
    }
    ... on Project {
      id
      name
      status
    }
    ... on User {
      id
      name
      email
    }
  }
}

119.text:
 query ListActiveProjects($status: ProjectStatus) {
  projects(status: $status) {
    totalCount
    nodes {
      id
      name
      status
      owner {
        name
      }
    }
  }
}

120.text:
 Archive a project that is no longer active. archiveProject(
  id: ID!
): Project!

123.text:
 mutation ArchiveProject($id: ID!) {
  archiveProject(id: $id) {
    id
    name
    status
    updatedAt
  }
}

128.text:
 mutation CreateFolder($name: String!, $parentId: ID) {
  createFolder(name: $name, parentId: $parentId) {
    id
    name
  }
}

129.text:
 Create a project and assign its initial owner. createProject(
  input: CreateProjectInput!
): Project!

132.text:
 mutation CreateProject($input: CreateProjectInput!) {
  createProject(input: $input) {
    id
    name
    status
    folder {
      id
      name
    }
  }
}
